scriptdefs
= MauvilleCity_EventScript_RolloutTutor
lock
faceplayer
goto_if_set FLAG_MOVE_TUTOR_TAUGHT_ROLLOUT MoveTutor_EventScript_RolloutTaught
msgboxyesno	Did you know that you can go from here a long way in that direction without changing direction?I might even be able to roll that way.Do you think your POKéMON will want to roll, too?I can teach one the move ROLLOUT if you'd like.
goto_if_eq VAR_RESULT NO MoveTutor_EventScript_RolloutDeclined
call MoveTutor_EventScript_CanOnlyBeLearnedOnce
goto_if_eq VAR_RESULT NO MoveTutor_EventScript_RolloutDeclined
msgbox	Ehehe, klar doch! Es wäre toll, wenn das POKéMON so aussehen würde wie ich.
setvar VAR_0x8005 TUTOR_MOVE_ROLLOUT
call MoveTutor_EventScript_OpenPartyMenu
goto_if_eq VAR_RESULT 0 MoveTutor_EventScript_RolloutDeclined
setflag FLAG_MOVE_TUTOR_TAUGHT_ROLLOUT
goto MoveTutor_EventScript_RolloutTaught
end
= MoveTutor_EventScript_RolloutTaught
msgbox	Sich im Gras zu wälzen macht mich glücklich. Los, wälzen wir uns!
release
end
= MoveTutor_EventScript_RolloutDeclined
msgbox	Du musst nicht schüchtern sein. Los, wälzen wir uns!
release
end
= MoveTutor_EventScript_OpenPartyMenu
special ChooseMonForMoveTutor
lock
faceplayer
return
= MoveTutor_EventScript_CanOnlyBeLearnedOnce
msgboxyesno	This move can be learned only once. Is that okay?
return
= MauvilleCity_EventScript_ItemXSpeed
goto_if_set FLAG_ITEM_MAUVILLE_CITY_X_SPEED MauvilleCity_EventScript_ItemXSpeed_Taken
finditem ITEM_X_SPEED
setflag FLAG_ITEM_MAUVILLE_CITY_X_SPEED
end
= MauvilleCity_EventScript_ItemXSpeed_Taken
end
= MauvilleCity_EventScript_Wattson
lock
faceplayer
goto_if_set FLAG_GOT_TM_THUNDERBOLT_FROM_WATTSON MauvilleCity_EventScript_ReceivedThunderbolt
goto_if_eq VAR_NEW_MAUVILLE_STATE 2 MauvilleCity_EventScript_CompletedNewMauville
goto_if_set FLAG_GOT_BASEMENT_KEY_FROM_WATTSON MauvilleCity_EventScript_BegunNewMauville
msgbox	WATTSON: Oh, PLAYER! Du siehst aus, als hättest du jede Menge Schwung! Das ist gut so, wahahahaha!Gut! Ich hab mich entschieden! Ich brauche einen Gefallen, PLAYER!MAUVILLE CITY hat einen unterirdischen Bereich namens NEU-MAUVILLE.PLAYER, ich möchte, dass du dorthin gehst und den GENERATOR abschaltest.Der GENERATOR läuft schon eine Weile verrückt. Das wird langsam gefährlich.Hier, das ist der SCHLÜSSEL für den Zugang zu NEU-MAUVILLE.
giveitem ITEM_BASEMENT_KEY
setflag FLAG_GOT_BASEMENT_KEY_FROM_WATTSON
msgbox	WATTSON: Mach dir mal keine Sorgen. Für dich wird das keine Herausforderung sein.Der Eingang zu NEU-MAUVILLE liegt nur ein kurzes SURFEN von ROUTE 110 entfernt.Gut, dann hast du mein Vertrauen! Wahahahaha!
release
end
= MauvilleCity_EventScript_BegunNewMauville
msgbox	WATTSON: Mach dir mal keine Sorgen. Für dich wird das keine Herausforderung sein.Der Eingang zu NEU-MAUVILLE liegt nur ein kurzes SURFEN von ROUTE 110 entfernt.Gut, dann hast du mein Vertrauen! Wahahahaha!
release
end
= MauvilleCity_EventScript_CompletedNewMauville
msgbox	WATTSON: Wahahahaha!Ich wusste es, PLAYER! Ich wusste, dass ich die richtige Wahl getroffen habe, als ich dich gefragt habe!Hier ist mein Dank--ein TM mit DONNERBLITZ!Nimm es ruhig, du hast es dir verdient!
giveitem ITEM_TM_THUNDERBOLT
goto_if_eq VAR_RESULT FALSE Common_EventScript_ShowBagIsFull
setflag FLAG_GOT_TM_THUNDERBOLT_FROM_WATTSON
msgbox	WATTSON: Wahahahaha!Es freut mich ungemein zu sehen, wie die Jugend Verantwortung übernimmt!
release
end
= MauvilleCity_EventScript_ReceivedThunderbolt
msgbox	WATTSON: Wahahahaha!Es freut mich ungemein zu sehen, wie die Jugend Verantwortung übernimmt!
release
end
= MauvilleCity_EventScript_WallysUncle
lock
faceplayer
goto_if_set FLAG_DECLINED_WALLY_BATTLE_MAUVILLE MauvilleCity_EventScript_UncleAskPlayerToBattleWally
msgbox	ONKEL: Ich schätze, wegen der POKéMON hat der Junge mehr Schwung bekommen… Aber er ist ein bisschen zu schwungvoll geworden…
closemessage
applymovement LOCALID_MAUVILLE_WALLYS_UNCLE Common_Movement_FaceOriginalDirection
waitmovement 0
release
end
= MauvilleCity_EventScript_UncleAskPlayerToBattleWally
msgbox	ONKEL: PLAYER, richtig? Kann ich dich im Namen von WALLY bitten, nur dieses eine Mal gegen ihn zu kämpfen?Ich glaube nicht, dass er im Moment auf Vernunft hört.
closemessage
applymovement LOCALID_MAUVILLE_WALLYS_UNCLE Common_Movement_FaceOriginalDirection
waitmovement 0
release
end
= MauvilleCity_EventScript_Wally
lockall
goto_if_set FLAG_DECLINED_WALLY_BATTLE_MAUVILLE MauvilleCity_EventScript_WallyRequestBattleAgain
applymovement LOCALID_MAUVILLE_WALLY Common_Movement_WalkInPlaceFasterRight
waitmovement 0
msgbox	WALLY: Ach, ONKEL, bitte?Ich will diese ARENA herausfordern und sehen, wie viel besser ich geworden bin.Bitte? Darf ich, bitte?
msgbox	ONKEL: Jetzt warte mal, WALLY.Seit du mit POKéMON lebst, bist du ziemlich viel stärker geworden.Aber findest du nicht, dass es übertrieben ist, plötzlich eine ARENA herauszufordern?
msgbox	WALLY: Das ist nicht übertrieben.Wenn ich meine Kräfte mit RALTS bündele, können wir jeden besiegen!
applymovement LOCALID_MAUVILLE_WALLY Common_Movement_FacePlayer
waitmovement 0
playse SE_PIN
applymovement LOCALID_MAUVILLE_WALLY Common_Movement_ExclamationMark
waitmovement 0
applymovement LOCALID_MAUVILLE_WALLY Common_Movement_Delay48
waitmovement 0
msgboxyesno	WALLY: Oh! Hi, PLAYER!I've gotten a lot stronger since we met.PLAYER, I want you and my UNCLE to understand that.PLAYER, please, will you have a battle with me?
goto MauvilleCity_EventScript_BattleWallyPrompt
end
= MauvilleCity_EventScript_BattleWallyPrompt
call_if_eq VAR_RESULT YES MauvilleCity_EventScript_BattleWally
goto_if_eq VAR_RESULT NO MauvilleCity_EventScript_DeclineWallyBattle
closemessage
switch VAR_FACING
case DIR_NORTH MauvilleCity_EventScript_WallyAndUncleExitNorth
case DIR_EAST MauvilleCity_EventScript_WallyAndUncleExitEast
end
= MauvilleCity_EventScript_WallyAndUncleExitEast
applymovement LOCALID_PLAYER MauvilleCity_Movement_PlayerWatchWallyExitEast1
applymovement LOCALID_MAUVILLE_WALLY MauvilleCity_Movement_WallyExitEast1
applymovement LOCALID_MAUVILLE_WALLYS_UNCLE MauvilleCity_Movement_WallysUncleExitEast1
waitmovement 0
applymovement LOCALID_MAUVILLE_WALLY Common_Movement_WalkInPlaceFasterRight
waitmovement 0
delay 30
applymovement LOCALID_MAUVILLE_WALLYS_UNCLE MauvilleCity_Movement_WallysUncleApproachPlayerEast
waitmovement 0
msgbox	ONKEL: PLAYER, mir wird gerade klar, dass du der TRAINER sein musst, der ein Auge auf WALLY hatte, als er sein POKéMON gefangen hat.Warum besuchst du uns nicht mal in VERDANTURF? Ich bin sicher, WALLY würde sich freuen.
closemessage
applymovement LOCALID_PLAYER MauvilleCity_Movement_PlayerWatchWallyExitEast2
applymovement LOCALID_MAUVILLE_WALLYS_UNCLE MauvilleCity_Movement_WallysUncleExitEast2
applymovement LOCALID_MAUVILLE_WALLY MauvilleCity_Movement_WallyExitEast2
waitmovement 0
goto MauvilleCity_EventScript_DefeatedWally
end
= MauvilleCity_EventScript_DefeatedWally
removeobject LOCALID_MAUVILLE_WALLY
removeobject LOCALID_MAUVILLE_WALLYS_UNCLE
clearflag FLAG_HIDE_VERDANTURF_TOWN_WANDAS_HOUSE_WALLY
clearflag FLAG_HIDE_VERDANTURF_TOWN_WANDAS_HOUSE_WALLYS_UNCLE
setflag FLAG_DEFEATED_WALLY_MAUVILLE
setvar VAR_WALLY_CALL_STEP_COUNTER 0
setflag FLAG_ENABLE_FIRST_WALLY_POKENAV_CALL
call_if_eq VAR_FACING DIR_NORTH MauvilleCity_EventScript_ScottApproachPlayerNorth
call_if_eq VAR_FACING DIR_EAST MauvilleCity_EventScript_ScottApproachPlayerEast
applymovement LOCALID_PLAYER Common_Movement_WalkInPlaceFasterDown
waitmovement 0
msgbox	SCOTT: Hehe… Ich hab mir den Kampf angesehen!Du bist doch mit dem Jungen WALLY befreundet, oder?Aber du hast dich nicht zurückgehalten und ihn beeindruckend besiegt.Ja! Genau darum geht es bei einem echten POKéMON-Kampf!Solche TRAINER bewundere ich!… … … … … … Ich werde dir die Daumen drücken!
closemessage
addvar VAR_SCOTT_STATE 1
call_if_eq VAR_FACING DIR_NORTH MauvilleCity_EventScript_ScottExitNorth
call_if_eq VAR_FACING DIR_EAST MauvilleCity_EventScript_ScottExitEast
removeobject LOCALID_MAUVILLE_SCOTT
releaseall
end
= MauvilleCity_EventScript_ScottExitEast
applymovement LOCALID_PLAYER MauvilleCity_Movement_PlayerWatchScottExitEast
applymovement LOCALID_MAUVILLE_SCOTT MauvilleCity_Movement_ScottExitEast
waitmovement 0
return
= MauvilleCity_EventScript_ScottExitNorth
applymovement LOCALID_PLAYER MauvilleCity_Movement_PlayerWatchScottExitNorth
applymovement LOCALID_MAUVILLE_SCOTT MauvilleCity_Movement_ScottExitNorth
waitmovement 0
return
= MauvilleCity_EventScript_ScottApproachPlayerEast
setobjectxyperm LOCALID_MAUVILLE_SCOTT 12 13
addobject LOCALID_MAUVILLE_SCOTT
applymovement LOCALID_MAUVILLE_SCOTT MauvilleCity_Movement_ScottApproachPlayerEast
waitmovement 0
return
= MauvilleCity_EventScript_ScottApproachPlayerNorth
addobject LOCALID_MAUVILLE_SCOTT
applymovement LOCALID_MAUVILLE_SCOTT MauvilleCity_Movement_ScottApproachPlayerNorth
waitmovement 0
return
= MauvilleCity_EventScript_WallyAndUncleExitNorth
applymovement LOCALID_PLAYER MauvilleCity_Movement_PlayerWatchWallyExitNorth1
applymovement LOCALID_MAUVILLE_WALLY MauvilleCity_Movement_WallyExitNorth1
applymovement LOCALID_MAUVILLE_WALLYS_UNCLE MauvilleCity_Movement_WallysUncleExitNorth1
waitmovement 0
applymovement LOCALID_MAUVILLE_WALLY Common_Movement_WalkInPlaceFasterRight
waitmovement 0
delay 30
applymovement LOCALID_PLAYER MauvilleCity_Movement_PlayerFaceUncleNorth
applymovement LOCALID_MAUVILLE_WALLYS_UNCLE MauvilleCity_Movement_WallysUncleApproachPlayerNorth
waitmovement 0
msgbox	ONKEL: PLAYER, mir wird gerade klar, dass du der TRAINER sein musst, der ein Auge auf WALLY hatte, als er sein POKéMON gefangen hat.Warum besuchst du uns nicht mal in VERDANTURF? Ich bin sicher, WALLY würde sich freuen.
closemessage
applymovement LOCALID_PLAYER MauvilleCity_Movement_PlayerWatchWallyExitNorth2
applymovement LOCALID_MAUVILLE_WALLYS_UNCLE MauvilleCity_Movement_WallysUncleExitNorth2
applymovement LOCALID_MAUVILLE_WALLY MauvilleCity_Movement_WallyExitNorth2
waitmovement 0
goto MauvilleCity_EventScript_DefeatedWally
end
= MauvilleCity_EventScript_DeclineWallyBattle
setflag FLAG_DECLINED_WALLY_BATTLE_MAUVILLE
msgbox	WALLY: Oh… Wenn du nicht gegen mich kämpfst, PLAYER, erfährt mein ONKEL nicht, dass ich wirklich stark geworden bin.
release
end
= MauvilleCity_EventScript_BattleWally
msgbox	WALLY: PLAYER, danke dir.Okay… Ich komme jetzt!
trainerbattle_no_intro TRAINER_WALLY_MAUVILLE MauvilleCity_Text_WallyDefeat
applymovement LOCALID_MAUVILLE_WALLY Common_Movement_WalkInPlaceFasterRight
waitmovement 0
msgbox	WALLY: ONKEL… Ich geh zurück nach VERDANTURF…
applymovement LOCALID_MAUVILLE_WALLY Common_Movement_FacePlayer
waitmovement 0
msgbox	PLAYER, danke dir. Ein TRAINER zu sein ist ganz schön hart, oder?Es reicht nicht, einfach POKéMON zu haben und sie kämpfen zu lassen. Das macht keinen echten TRAINER aus.
applymovement LOCALID_MAUVILLE_WALLY Common_Movement_WalkInPlaceFasterRight
waitmovement 0
msgbox	ONKEL: WALLY, du musst dich deswegen nicht so runtermachen.Was hält dich denn davon ab, immer stärker zu werden?Komm, lass uns nach Hause gehen. Alle warten auf dich.
return
= MauvilleCity_EventScript_WallyRequestBattleAgain
applymovement LOCALID_MAUVILLE_WALLY Common_Movement_FacePlayer
waitmovement 0
msgboxyesno	WALLY: PLAYER, please! Battle with me, please.
goto MauvilleCity_EventScript_BattleWallyPrompt
end
= MauvilleCity_EventScript_SchoolKidM
lock
faceplayer
goto_if_set FLAG_TV_EXPLAINED MauvilleCity_EventScript_TVExplained
msgbox	Hi, schaust du eigentlich manchmal fern?Die haben vor Kurzem ein paar coole neue Sendungen dazubekommen.Fernsehen ist so cool. Ich hab meine Freunde schon aus heiterem Himmel im Fernsehen gesehen.Und manchmal zeigen sie einen sogar im Fernsehen, ohne einem Bescheid zu geben.Ich wünschte, ich käme auch mal ins Fernsehen.Deshalb finde ich, du solltest so oft wie möglich fernsehen.
setflag FLAG_TV_EXPLAINED
release
end
= MauvilleCity_EventScript_TVExplained
msgbox	Hi, schaust du eigentlich fern?
release
end
